mapper.select:
select

from MST_HOLIDAY
where CALENDAR_ID = #{calendarId,jdbcType=VARCHAR}
and CDATE = #{cdate,jdbcType=TIMESTAMP}

mapper.delete:
delete from MST_HOLIDAY
where CALENDAR_ID = #{calendarId,jdbcType=VARCHAR}
  and CDATE = #{cdate,jdbcType=TIMESTAMP}

mapper.update:
update MST_HOLIDAY
set IS_HOLIDAY = #{isHoliday,jdbcType=DECIMAL},
  CREATE_USER = #{createUser,jdbcType=VARCHAR},
  CREATE_DEPT = #{createDept,jdbcType=VARCHAR},
  CREATE_TIME = #{createTime,jdbcType=TIMESTAMP},
  UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
  UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where CALENDAR_ID = #{calendarId,jdbcType=VARCHAR}
  and CDATE = #{cdate,jdbcType=TIMESTAMP}

mapper.insert:
insert into MST_HOLIDAY(CALENDAR_ID, CDATE, IS_HOLIDAY, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select CALENDAR_ID, CDATE, IS_HOLIDAY, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.calendarId,jdbcType=VARCHAR} CALENDAR_ID, #{item.cdate,jdbcType=TIMESTAMP} CDATE, #{item.isHoliday,jdbcType=DECIMAL} IS_HOLIDAY, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, NOW() CREATE_TIME, #{item.createUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME FROM DUAL
) TEMP where not exists (select 1 from MST_HOLIDAY CII where CII.CALENDAR_ID = TEMP.CALENDAR_ID AND DATE_FORMAT(CII.CDATE,'%Y-%m-%d') = DATE_FORMAT(TEMP.CDATE,'%Y-%m-%d')) ) de ;
UPDATE MST_HOLIDAY as A, ( select CALENDAR_ID, CDATE, IS_HOLIDAY, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.calendarId,jdbcType=VARCHAR} CALENDAR_ID, #{item.cdate,jdbcType=TIMESTAMP} CDATE, #{item.isHoliday,jdbcType=DECIMAL} IS_HOLIDAY, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, NOW() CREATE_TIME, #{item.createUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME FROM DUAL
) TEMP ) de ) AS B SET A.IS_HOLIDAY = B.IS_HOLIDAY, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME where A.CALENDAR_ID = B.CALENDAR_ID AND DATE_FORMAT(A.CDATE,'%Y-%m-%d') = DATE_FORMAT(B.CDATE,'%Y-%m-%d');
